<?php
require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';$user=Auth::requireRole('hospital');$hospital=current_hospital($user);$errors=[];
if(request_method('POST')){Csrf::verify();$title=trim($_POST['title']??'');$district=$_POST['district']??'';$location=trim($_POST['location']??'');$date=$_POST['event_date']??'';$start=$_POST['start_time']??'';$end=$_POST['end_time']??'';$capacity=(int)($_POST['capacity']??0);$notes=trim($_POST['notes']??'');if(strlen($title)<4)$errors[]='Enter a campaign title.';if(!validate_district($district))$errors[]='Select a valid district.';if(strlen($location)<4)$errors[]='Enter a location.';if(!$date||strtotime($date)<strtotime(date('Y-m-d')))$errors[]='Select a current or future date.';if(!$start||!$end||$start>=$end)$errors[]='Select a valid time range.';if($capacity<1||$capacity>2000)$errors[]='Capacity must be between 1 and 2000.';if(!$errors){db()->prepare('INSERT INTO donation_campaigns(hospital_id,title,district,location,event_date,start_time,end_time,capacity,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([(int)$hospital['id'],$title,$district,$location,$date,$start,$end,$capacity,$notes?:null,(int)$user['id']]);$id=(int)db()->lastInsertId();audit('campaign_created','campaign',$id);flash('success','Donation campaign created.');redirect('hospital/campaigns.php');}}
$q=db()->prepare("SELECT c.*,(SELECT COUNT(*) FROM campaign_registrations cr WHERE cr.campaign_id=c.id AND cr.status='booked') booked FROM donation_campaigns c WHERE c.hospital_id=? ORDER BY c.event_date DESC,c.start_time DESC");$q->execute([(int)$hospital['id']]);$rows=$q->fetchAll();$pageTitle='Donation Campaigns';require dirname(dirname(__DIR__)).'/src/templates/header.php';?>
<section class="dashboard"><div class="container"><div class="dash-head"><div><div class="eyebrow">Hospital workspace</div><h1>Donation campaigns</h1><p class="page-note">Create simple blood-donation events and manage donor appointment attendance.</p></div></div><?=hospital_nav($user)?><div class="grid-2"><div class="card"><h2>Create campaign</h2><?php if($errors):?><div class="error-list"><?=e(implode(' ',$errors))?></div><?php endif;?><form method="post"><?=Csrf::field()?><div class="field"><label>Campaign title</label><input name="title" required maxlength="160"></div><div class="form-grid"><div class="field"><label>District</label><select name="district"><?php foreach(districts() as $d):?><option <?=$hospital['district']===$d?'selected':''?>><?=e($d)?></option><?php endforeach;?></select></div><div class="field"><label>Capacity</label><input type="number" name="capacity" min="1" max="2000" value="50" required></div><div class="field"><label>Date</label><input type="date" name="event_date" min="<?=e(date('Y-m-d'))?>" required></div><div class="field"><label>Location</label><input name="location" value="<?=e($hospital['address'])?>" required></div><div class="field"><label>Start time</label><input type="time" name="start_time" value="09:00" required></div><div class="field"><label>End time</label><input type="time" name="end_time" value="15:00" required></div></div><div class="field"><label>Notes</label><textarea name="notes" maxlength="500"></textarea></div><button class="btn">Create Campaign</button></form></div><div><h2>Campaigns</h2><div class="table-wrap"><table class="table"><thead><tr><th>Campaign</th><th>Date</th><th>Bookings</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="empty">No campaigns yet.</td></tr><?php endif;?><?php foreach($rows as $c):?><tr><td><strong><?=e($c['title'])?></strong><br><span class="small"><?=e($c['location'])?></span></td><td><?=e($c['event_date'])?></td><td><?=e((string)$c['booked'])?> / <?=e((string)$c['capacity'])?></td><td><span class="badge <?=$c['status']==='active'?'green':'gray'?>"><?=e($c['status'])?></span></td><td><a href="<?=e(url('hospital/campaign-detail.php?id='.(int)$c['id']))?>">Manage</a></td></tr><?php endforeach;?></tbody></table></div></div></div></div></section>
<?php require dirname(dirname(__DIR__)).'/src/templates/footer.php';?>
